import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_src = "at::Tensor ln_forward(at::Tensor x, at::Tensor weight, at::Tensor bias, double eps);"

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <algorithm>
#include <cstdint>
template <typename T, int BLOCK>
__device__ inline void warp_reduce_pair(T &sum, T &sq) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
        sq  += __shfl_down_sync(0xffffffff, sq, offset);
    }
}
template <typename T, int BLOCK>
__device__ inline void block_reduce_pair(T &sum, T &sq, T *red_sum, T *red_sq) {
    constexpr int NWARPS = BLOCK / 32;
    const int tid = threadIdx.x;
    const int lane = tid & 31;
    const int wid = tid >> 5;
    warp_reduce_pair<T, BLOCK>(sum, sq);
    if (lane == 0) {
        red_sum[wid] = sum;
        red_sq[wid] = sq;
    }
    __syncthreads();
    if (wid == 0) {
        T s = (lane < NWARPS) ? red_sum[lane] : (T)0;
        T q = (lane < NWARPS) ? red_sq[lane] : (T)0;
        warp_reduce_pair<T, BLOCK>(s, q);
        if (lane == 0) {
            red_sum[0] = s;
            red_sq[0] = q;
        }
    }
    __syncthreads();
    if (tid == 0) {
        sum = red_sum[0];
        sq = red_sq[0];
    }
    __syncthreads();
}
template <typename T, int BLOCK>
__global__ void ln_stats_kernel(
    const T *__restrict__ x,
    T *__restrict__ acc,
    int64_t N,
    int64_t chunks_per_row,
    int64_t total_chunks,
    int chunk_elems,
    int vec_ok) {
    __shared__ T red_sum[BLOCK / 32];
    __shared__ T red_sq[BLOCK / 32];
    const int tid = threadIdx.x;
    for (int64_t chunk = blockIdx.x; chunk < total_chunks; chunk += gridDim.x) {
        int64_t row = chunk / chunks_per_row;
        int64_t cin = chunk - row * chunks_per_row;
        int64_t within = cin * (int64_t)chunk_elems;
        int64_t off = row * N + within;
        int64_t rem = N - within;
        int len = rem < (int64_t)chunk_elems ? (int)rem : chunk_elems;
        T lsum0 = (T)0;
        T lsum1 = (T)0;
        T lsq0 = (T)0;
        T lsq1 = (T)0;
        if (vec_ok) {
            const float4 *x4 = reinterpret_cast<const float4 *>(x + off);
            int n4 = len >> 2;
            int i = tid;
            for (; i + 3 * BLOCK < n4; i += 4 * BLOCK) {
                float4 v0 = x4[i];
                float4 v1 = x4[i + BLOCK];
                float4 v2 = x4[i + 2 * BLOCK];
                float4 v3 = x4[i + 3 * BLOCK];
                lsum0 += (T)v0.x + (T)v0.y + (T)v0.z + (T)v0.w;
                lsum1 += (T)v1.x + (T)v1.y + (T)v1.z + (T)v1.w;
                lsum0 += (T)v2.x + (T)v2.y + (T)v2.z + (T)v2.w;
                lsum1 += (T)v3.x + (T)v3.y + (T)v3.z + (T)v3.w;
                lsq0 += (T)v0.x * (T)v0.x + (T)v0.y * (T)v0.y + (T)v0.z * (T)v0.z + (T)v0.w * (T)v0.w;
                lsq1 += (T)v1.x * (T)v1.x + (T)v1.y * (T)v1.y + (T)v1.z * (T)v1.z + (T)v1.w * (T)v1.w;
                lsq0 += (T)v2.x * (T)v2.x + (T)v2.y * (T)v2.y + (T)v2.z * (T)v2.z + (T)v2.w * (T)v2.w;
                lsq1 += (T)v3.x * (T)v3.x + (T)v3.y * (T)v3.y + (T)v3.z * (T)v3.z + (T)v3.w * (T)v3.w;
            }
            for (; i < n4; i += BLOCK) {
                float4 v = x4[i];
                lsum0 += (T)v.x + (T)v.y + (T)v.z + (T)v.w;
                lsq0 += (T)v.x * (T)v.x + (T)v.y * (T)v.y + (T)v.z * (T)v.z + (T)v.w * (T)v.w;
            }
            for (int j = (n4 << 2) + tid; j < len; j += BLOCK) {
                T v = x[off + j];
                lsum1 += v;
                lsq1 += v * v;
            }
        } else {
            int i = tid;
            for (; i + 3 * BLOCK < len; i += 4 * BLOCK) {
                T v0 = x[off + i];
                T v1 = x[off + i + BLOCK];
                T v2 = x[off + i + 2 * BLOCK];
                T v3 = x[off + i + 3 * BLOCK];
                lsum0 += v0 + v2;
                lsum1 += v1 + v3;
                lsq0 += v0 * v0 + v2 * v2;
                lsq1 += v1 * v1 + v3 * v3;
            }
            for (; i < len; i += BLOCK) {
                T v = x[off + i];
                lsum0 += v;
                lsq0 += v * v;
            }
        }
        T lsum = lsum0 + lsum1;
        T lsq = lsq0 + lsq1;
        block_reduce_pair<T, BLOCK>(lsum, lsq, red_sum, red_sq);
        if (tid == 0) {
            acc[chunk * 2 + 0] = lsum;
            acc[chunk * 2 + 1] = lsq;
        }
        __syncthreads();
    }
}
template <typename T, int BLOCK>
__global__ void ln_finalize_kernel(
    const T *__restrict__ acc,
    T *__restrict__ stats,
    int64_t outer,
    int64_t N,
    int64_t chunks_per_row,
    T eps) {
    __shared__ T red_sum[BLOCK / 32];
    __shared__ T red_sq[BLOCK / 32];
    const int tid = threadIdx.x;
    for (int64_t row = blockIdx.x; row < outer; row += gridDim.x) {
        T sum = (T)0;
        T sq = (T)0;
        const int64_t base = row * chunks_per_row;
        for (int64_t c = tid; c < chunks_per_row; c += BLOCK) {
            sum += acc[(base + c) * 2 + 0];
            sq += acc[(base + c) * 2 + 1];
        }
        block_reduce_pair<T, BLOCK>(sum, sq, red_sum, red_sq);
        if (tid == 0) {
            T mean = sum / (T)N;
            T var = sq / (T)N - mean * mean;
            if (var < (T)0) var = (T)0;
            stats[row * 2 + 0] = mean;
            stats[row * 2 + 1] = rsqrt(var + eps);
        }
        __syncthreads();
    }
}
template <typename T, int BLOCK>
__global__ void ln_normalize_kernel(
    const T *__restrict__ x,
    const T *__restrict__ w,
    const T *__restrict__ b,
    T *__restrict__ y,
    const T *__restrict__ stats,
    int64_t N,
    int64_t chunks_per_row,
    int64_t total_blocks,
    int chunk_elems,
    int vec_ok) {
    const int tid = threadIdx.x;
    for (int64_t blk = blockIdx.x; blk < total_blocks; blk += gridDim.x) {
        int64_t row = blk / chunks_per_row;
        int64_t cin = blk - row * chunks_per_row;
        int64_t within = cin * (int64_t)chunk_elems;
        int64_t rem = N - within;
        int len = rem < (int64_t)chunk_elems ? (int)rem : chunk_elems;
        int64_t off = row * N + within;
        const T mean = stats[row * 2 + 0];
        const T rstd = stats[row * 2 + 1];
        if (vec_ok) {
            const float4 *x4 = reinterpret_cast<const float4 *>(x + off);
            const float4 *w4 = reinterpret_cast<const float4 *>(w + within);
            const float4 *b4 = reinterpret_cast<const float4 *>(b + within);
            float4 *y4 = reinterpret_cast<float4 *>(y + off);
            int n4 = len >> 2;
            int i = tid;
            for (; i + 3 * BLOCK < n4; i += 4 * BLOCK) {
                float4 x0 = x4[i];
                float4 x1 = x4[i + BLOCK];
                float4 x2 = x4[i + 2 * BLOCK];
                float4 x3 = x4[i + 3 * BLOCK];
                float4 w0 = w4[i];
                float4 w1 = w4[i + BLOCK];
                float4 w2 = w4[i + 2 * BLOCK];
                float4 w3 = w4[i + 3 * BLOCK];
                float4 b0 = b4[i];
                float4 b1 = b4[i + BLOCK];
                float4 b2 = b4[i + 2 * BLOCK];
                float4 b3 = b4[i + 3 * BLOCK];
                float4 y0;
                float4 y1;
                float4 y2;
                float4 y3;
                y0.x = ((T)x0.x - mean) * rstd * (T)w0.x + (T)b0.x;
                y0.y = ((T)x0.y - mean) * rstd * (T)w0.y + (T)b0.y;
                y0.z = ((T)x0.z - mean) * rstd * (T)w0.z + (T)b0.z;
                y0.w = ((T)x0.w - mean) * rstd * (T)w0.w + (T)b0.w;
                y1.x = ((T)x1.x - mean) * rstd * (T)w1.x + (T)b1.x;
                y1.y = ((T)x1.y - mean) * rstd * (T)w1.y + (T)b1.y;
                y1.z = ((T)x1.z - mean) * rstd * (T)w1.z + (T)b1.z;
                y1.w = ((T)x1.w - mean) * rstd * (T)w1.w + (T)b1.w;
                y2.x = ((T)x2.x - mean) * rstd * (T)w2.x + (T)b2.x;
                y2.y = ((T)x2.y - mean) * rstd * (T)w2.y + (T)b2.y;
                y2.z = ((T)x2.z - mean) * rstd * (T)w2.z + (T)b2.z;
                y2.w = ((T)x2.w - mean) * rstd * (T)w2.w + (T)b2.w;
                y3.x = ((T)x3.x - mean) * rstd * (T)w3.x + (T)b3.x;
                y3.y = ((T)x3.y - mean) * rstd * (T)w3.y + (T)b3.y;
                y3.z = ((T)x3.z - mean) * rstd * (T)w3.z + (T)b3.z;
                y3.w = ((T)x3.w - mean) * rstd * (T)w3.w + (T)b3.w;
                y4[i] = y0;
                y4[i + BLOCK] = y1;
                y4[i + 2 * BLOCK] = y2;
                y4[i + 3 * BLOCK] = y3;
            }
            for (; i < n4; i += BLOCK) {
                float4 xv = x4[i];
                float4 wv = w4[i];
                float4 bv = b4[i];
                float4 yv;
                yv.x = ((T)xv.x - mean) * rstd * (T)wv.x + (T)bv.x;
                yv.y = ((T)xv.y - mean) * rstd * (T)wv.y + (T)bv.y;
                yv.z = ((T)xv.z - mean) * rstd * (T)wv.z + (T)bv.z;
                yv.w = ((T)xv.w - mean) * rstd * (T)wv.w + (T)bv.w;
                y4[i] = yv;
            }
            for (int j = (n4 << 2) + tid; j < len; j += BLOCK) {
                T xv = x[off + j];
                y[off + j] = (xv - mean) * rstd * w[within + j] + b[within + j];
            }
        } else {
            int i = tid;
            for (; i + 3 * BLOCK < len; i += 4 * BLOCK) {
                T x0 = x[off + i];
                T x1 = x[off + i + BLOCK];
                T x2 = x[off + i + 2 * BLOCK];
                T x3 = x[off + i + 3 * BLOCK];
                y[off + i] = (x0 - mean) * rstd * w[within + i] + b[within + i];
                y[off + i + BLOCK] = (x1 - mean) * rstd * w[within + i + BLOCK] + b[within + i + BLOCK];
                y[off + i + 2 * BLOCK] = (x2 - mean) * rstd * w[within + i + 2 * BLOCK] + b[within + i + 2 * BLOCK];
                y[off + i + 3 * BLOCK] = (x3 - mean) * rstd * w[within + i + 3 * BLOCK] + b[within + i + 3 * BLOCK];
            }
            for (; i < len; i += BLOCK) {
                T xv = x[off + i];
                y[off + i] = (xv - mean) * rstd * w[within + i] + b[within + i];
            }
        }
    }
}
template <typename T>
at::Tensor ln_forward_t(at::Tensor x, at::Tensor weight, at::Tensor bias, double eps) {
    constexpr int BLOCK = 256;
    auto xc = x.contiguous();
    auto wc = weight.contiguous();
    auto bc = bias.contiguous();
    auto y = at::empty_like(xc);
    const int64_t N = wc.numel();
    const int64_t total = xc.numel();
    TORCH_CHECK(N > 0);
    TORCH_CHECK(total % N == 0);
    const int64_t outer = total / N;
    auto stream = at::cuda::getCurrentCUDAStream();
    auto stats = at::empty({outer * 2}, xc.options());
    const int vec_ok = (((N & 3) == 0) &&
                        (sizeof(T) == 4) &&
                        (reinterpret_cast<uintptr_t>(xc.data_ptr<T>()) % 16 == 0) &&
                        (reinterpret_cast<uintptr_t>(wc.data_ptr<T>()) % 16 == 0) &&
                        (reinterpret_cast<uintptr_t>(bc.data_ptr<T>()) % 16 == 0) &&
                        (reinterpret_cast<uintptr_t>(y.data_ptr<T>())  % 16 == 0)) ? 1 : 0;
    const int chunk_elems = vec_ok ? BLOCK * 16 : BLOCK * 4;
    const int64_t chunks_per_row = (N + chunk_elems - 1) / chunk_elems;
    const int64_t total_chunks = outer * chunks_per_row;
    auto acc = at::empty({total_chunks * 2}, xc.options());
    int dev = 0;
    cudaGetDevice(&dev);
    int sm_count = 0;
    cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, dev);
    if (sm_count < 1) sm_count = 1;
    int64_t want_blocks = (int64_t)sm_count * 8;
    int num_blocks = (int)std::min<int64_t>(want_blocks, total_chunks);
    if (num_blocks < 1) num_blocks = 1;
    ln_stats_kernel<T, BLOCK><<<num_blocks, BLOCK, 0, stream.stream()>>>(
        xc.data_ptr<T>(),
        acc.data_ptr<T>(),
        N,
        chunks_per_row,
        total_chunks,
        chunk_elems,
        vec_ok);
    constexpr int FIN_BLOCK = 256;
    const int64_t fin_blocks_needed = std::min<int64_t>(outer, (int64_t)sm_count * 8);
    const int fin_blocks = fin_blocks_needed > 0 ? (int)fin_blocks_needed : 1;
    ln_finalize_kernel<T, FIN_BLOCK><<<fin_blocks, FIN_BLOCK, 0, stream.stream()>>>(
        acc.data_ptr<T>(),
        stats.data_ptr<T>(),
        outer,
        N,
        chunks_per_row,
        (T)eps);
    const int64_t grid_cap = (int64_t)1 << 30;
    int num_norm_blocks = (int)std::min<int64_t>(total_chunks, grid_cap);
    if (num_norm_blocks < 1) num_norm_blocks = 1;
    ln_normalize_kernel<T, BLOCK><<<num_norm_blocks, BLOCK, 0, stream.stream()>>>(
        xc.data_ptr<T>(),
        wc.data_ptr<T>(),
        bc.data_ptr<T>(),
        y.data_ptr<T>(),
        stats.data_ptr<T>(),
        N,
        chunks_per_row,
        total_chunks,
        chunk_elems,
        vec_ok);
    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "ln kernels launch failed: ",
                cudaGetErrorString(err));
    return y;
}
at::Tensor ln_forward(at::Tensor x, at::Tensor weight, at::Tensor bias, double eps) {
    TORCH_CHECK(x.is_cuda() && weight.is_cuda() && bias.is_cuda());
    TORCH_CHECK(x.scalar_type() == weight.scalar_type() && x.scalar_type() == bias.scalar_type());
    if (x.scalar_type() == at::kFloat) {
        return ln_forward_t<float>(x, weight, bias, eps);
    }
    if (x.scalar_type() == at::kDouble) {
        return ln_forward_t<double>(x, weight, bias, eps);
    }
    TORCH_CHECK(false);
}
"""

_C = load_inline(
    name="custom_layernorm_persistent",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["ln_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5
        self.ln = nn.Module()
        self.ln.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.ln.bias = nn.Parameter(torch.zeros(self.normalized_shape))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _C.ln_forward(x, self.ln.weight, self.ln.bias, self.eps)

