template <typename T>
__global__ void ln_finalize_kernel(
    const T *__restrict__ acc,
    T *__restrict__ stats,
    int64_t outer,
    int64_t N,
    T eps) {
    const int64_t stride = (int64_t)gridDim.x * blockDim.x;
    for (int64_t row = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; row < outer; row += stride) {
        T s = acc[row * 2 + 0];
